/* A member's own dated activity journal, separate from management analytics. */
(()=>{'use strict';const shared=document.body.classList.contains('shared-app'),q=s=>document.querySelector(s),key='my-work-report';let generation=0,from='',to='',lastReport=null;const dayKey=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(d)),today=()=>dayKey(Date.now()),fmt=s=>new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeZone:'Asia/Tehran'}).format(new Date(s.length===10?s+'T12:00:00Z':s)),num=n=>Number(n).toLocaleString('fa-IR'),escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));to=today();from=window.SamandisDates?SamandisDates.parse(SamandisDates.display(to).split('/').slice(0,2).join('/')+'/1'):to.slice(0,8)+'01';
const button=document.createElement('button');button.id='myWorkReportNav';button.innerHTML='<span aria-hidden="true">▤</span><span>گزارش کار من</span>';button.onclick=()=>{if(shared&&!mine())return message('ابتدا وارد حساب خود شوید.');if(window.SAMANDIS_PERSONAL_MODE)document.querySelector('[data-team-return]')?.click();if(shared){scope=key;render()}else{view=key;render()}};q('#deskNav').append(button);
const eventNames={report:'گزارش کار / بازخورد',submit:'اعلام انجام کار',approve:'تأیید کار',file:'بارگذاری فایل',created:'تعریف کار',assign:'ارجاع کار',edit:'ویرایش کار',reopen:'بازگشایی کار',correct:'درخواست اصلاح',request:'درخواست همکاری',trash:'حذف کار',restore:'بازیابی کار',import:'ورود اطلاعات'};
async function allRows(factory){let result=[];for(let offset=0;;offset+=500){const rows=await checked(factory().range(offset,offset+499));result.push(...rows);if(rows.length<500)return result}}
function table(report){const grouped=new Map();for(const item of report.items){if(!grouped.has(item.day))grouped.set(item.day,[]);grouped.get(item.day).push(item)}return '<article class="own-report-paper"><header><small>شرکت سمندیس · '+escape(report.project)+'</small><h1>گزارش تجمعی کارکرد شخصی</h1><h2>'+escape(report.name)+'</h2><p>'+fmt(report.from)+' تا '+fmt(report.to)+'</p><small>تهیه‌شده در '+fmt(today())+'</small></header><div class="own-report-totals"><span>'+num(report.items.length)+' فعالیت ثبت‌شده</span><span>'+num(grouped.size)+' روز دارای فعالیت</span><span>'+num(new Set(report.items.map(i=>i.taskId).filter(Boolean)).size)+' کار</span><span>'+num(report.hours)+' ساعت کارکرد ثبت‌شده</span></div><p class="own-report-note">این گزارش شامل فعالیت‌ها و ساعت‌هایی است که به نام این فرد ثبت شده‌اند؛ ساعت کارکرد با زمان حضور در سایت متفاوت است.</p>'+[...grouped.entries()].sort((a,b)=>a[0].localeCompare(b[0])).map(([date,items])=>'<section class="own-report-day"><h3>'+fmt(date)+'</h3><table><thead><tr><th>کار</th><th>فعالیت / شرح کار انجام‌شده</th><th>ساعت ثبت‌شده</th></tr></thead><tbody>'+items.map(i=>'<tr><td>'+escape(i.title)+'</td><td><b>'+escape(i.kind)+'</b>'+(i.text?'<p>'+escape(i.text)+'</p>':'')+'</td><td>'+(i.hours?num(i.hours):'—')+'</td></tr>').join('')+'</tbody></table></section>').join('')+(report.items.length?'':'<p>در این بازه فعالیتی به نام شما ثبت نشده است.</p>')+'<footer>گزارش شخصی عضو · این خروجی گزارش ارزیابی مدیریتی نیست.</footer></article>'}
const paperCss='body{direction:rtl;font-family:Tahoma,sans-serif;color:#263c55;margin:24px;font-size:12px;line-height:1.9}header{text-align:center;border-bottom:2px solid #425b7c;padding-bottom:15px}h1{font-size:20px}h2{font-size:16px}.own-report-totals{display:flex;flex-wrap:wrap;gap:16px;padding:16px 0;border-bottom:1px solid #ccc}.own-report-note,footer{font-size:11px;color:#53657c}table{width:100%;border-collapse:collapse;table-layout:fixed}td,th{text-align:right;border:1px solid #d5dce5;padding:9px;vertical-align:top;overflow-wrap:anywhere}th{background:#eef2f7}td p{white-space:pre-wrap;margin:4px 0}tr{break-inside:avoid}thead{display:table-header-group}h3{break-after:avoid}footer{margin-top:24px;border-top:1px solid #ccc;padding-top:12px}@page{size:A4;margin:15mm}';
function htmlReport(){return '<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><title>گزارش کار شخصی</title><style>'+paperCss+'</style><body>'+table(lastReport)+'</body></html>'}
function print(){if(!lastReport)return;const frame=document.createElement('iframe');frame.className='own-report-print-frame';frame.title='چاپ گزارش شخصی';frame.onload=()=>{frame.contentWindow.focus();frame.contentWindow.print()};frame.srcdoc=htmlReport();document.querySelector('.own-report-print-frame')?.remove();document.body.append(frame)}
function download(){if(!lastReport)return;const blob=new Blob(['\ufeff'+htmlReport()],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='گزارش-کار-'+lastReport.from+'-'+lastReport.to+'.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function load(){const token=++generation,host=q(shared?'#sharedContent':'#workspace'),uid=shared?session?.user.id:me(),pid=shared?project?.id:'demo',memberId=shared?mine()?.id:me();if(!host||shared&&!memberId)return;lastReport=null;host.innerHTML='<section class="own-report"><h1>گزارش کار من</h1><p class="shared-meta">فعالیت‌های خودتان را در بازهٔ دلخواه جمع‌بندی، دریافت یا چاپ کنید.</p><form id="ownReportRange" class="range-controls"><label>از تاریخ<input type="date" name="from" value="'+from+'" required></label><label>تا تاریخ<input type="date" name="to" value="'+to+'" required></label><button class="primary">تهیه گزارش</button></form><div class="own-report-actions"><button id="ownReportPrint" class="primary" disabled>چاپ / ذخیره PDF</button><button id="ownReportDownload" class="secondary" disabled>دریافت گزارش</button></div><div id="ownReportBody" aria-live="polite">در حال تهیه گزارش…</div></section>';q('#ownReportRange').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),a=f.get('from'),b=f.get('to');if(!a||!b||a>b)return(shared?message:toast)('بازهٔ تاریخ معتبر نیست.');from=a;to=b;load()};q('#ownReportPrint').onclick=print;q('#ownReportDownload').onclick=download;const a=from,b=to;
try{let items=[],hours=0;if(shared){const end=new Date(b+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+1);const upper=end.toISOString().slice(0,10)+'T00:00:00+03:30';const [events,logs]=await Promise.all([allRows(()=>db.from('sm_events').select('*,task:sm_tasks(title)').eq('project_id',pid).eq('actor_id',memberId).gte('created_at',a+'T00:00:00+03:30').lt('created_at',upper).order('created_at')),allRows(()=>db.from('sm_worklogs').select('*,task:sm_tasks(title)').eq('project_id',pid).eq('member_id',memberId).gte('work_date',a).lte('work_date',b).order('work_date'))]);items=events.map(e=>({day:dayKey(e.created_at),taskId:e.task_id,title:e.task?.title||'کار',kind:eventNames[e.kind]||'فعالیت',text:e.text||'',hours:0}));items.push(...logs.map(l=>({day:l.work_date,taskId:l.task_id,title:l.task?.title||'کار',kind:'کارکرد ثبت‌شده',text:l.description,hours:Number(l.hours)})));hours=logs.reduce((s,l)=>s+Number(l.hours),0)}else{items=logs().filter(l=>l.person===memberId&&dayKey(l.time)>=a&&dayKey(l.time)<=b).map(l=>({day:dayKey(l.time),taskId:l.taskId||l.task,title:l.task,kind:'فعالیت ثبت‌شده',text:l.text,hours:Number(l.hours)||0}));hours=items.reduce((s,i)=>s+i.hours,0)}if(token!==generation||(shared?(scope!==key||session?.user.id!==uid||project?.id!==pid):view!==key))return;lastReport={uid,pid,name:shared?mine().name:people[me()],project:shared?project.name:'پروژه دارایی',from:a,to:b,items,hours};q('#ownReportBody').innerHTML=table(lastReport);q('#ownReportPrint').disabled=false;q('#ownReportDownload').disabled=false}catch(e){if(token===generation&&q('#ownReportBody'))q('#ownReportBody').textContent=shared?failure(e):e.message}}
const oldRender=render;render=function(...args){const active=(shared?scope:view)===key;if(active&&lastReport&&lastReport.uid===(shared?session?.user.id:me())&&lastReport.pid===(shared?project?.id:'demo')&&q('#ownReportBody'))return;if(!shared&&active){view='mine';try{oldRender(...args)}finally{view=key}}else oldRender(...args);button.classList.toggle('active',active);if(active){document.querySelectorAll('[data-desk-view]').forEach(b=>b.classList.remove('active'));q('#deskCrumb').textContent='گزارش کار من';load()}else{generation++;lastReport=null}};
})();
